"""Focused compatibility/integrity checks; no fit, sampling or evaluation."""
import hashlib
import json
from pathlib import Path
import shutil
import tempfile
import unittest
from unittest.mock import patch

import src.revision_a1_runtime as runtime
import src.revision_forest as forest
from src.revision_artifact_reader import (
    ReadOnlyArtifactReader, verify_format, approved_digest, _forest_checker,
    GREAT_PATH, ORIGINAL_SHA256, FORMATTED_SHA256,
)


class ApprovedFormatTests(unittest.TestCase):
    def test_current_source_exact_diff_and_ast(self):
        source=GREAT_PATH.read_bytes();report=verify_format(source)
        self.assertEqual(report['actual_sha256'],FORMATTED_SHA256)
        self.assertTrue(report['ast_equal'])
        changes=[s for s in report['diff'].splitlines() if s.startswith(('+','-')) and not s.startswith(('+++','---'))]
        self.assertEqual(len(changes),4)
        old=source.replace(b'    model_pt = ',b'    model_pt    = ').replace(b'    buffer = ',b'    buffer     = ')
        self.assertEqual(verify_format(old)['actual_sha256'],ORIGINAL_SHA256)

    def test_future_format_and_semantic_edits_are_rejected(self):
        source=GREAT_PATH.read_bytes()
        for changed in (source+b'\n',source.replace(b'weights_only=True',b'weights_only=False')):
            with self.assertRaisesRegex(ValueError,'Unapproved'):verify_format(changed)

    def test_digest_exception_is_one_path_only_and_not_global(self):
        self.assertEqual(approved_digest(GREAT_PATH),ORIGINAL_SHA256)
        self.assertEqual(runtime.digest(GREAT_PATH),FORMATTED_SHA256)
        other=runtime.ROOT_DIR/'src/utils/seed_utils.py'
        self.assertEqual(approved_digest(other),runtime.digest(other))

    def test_forest_namespace_is_private_read_only_and_source_pinned(self):
        path=runtime.ROOT_DIR/'src/revision_forest.py';before=forest.digest
        checker=_forest_checker(runtime.digest(path));namespace=checker.__globals__
        self.assertIs(forest.digest,before)
        self.assertIsNot(namespace,forest.__dict__)
        self.assertEqual(forest.digest(GREAT_PATH),FORMATTED_SHA256)
        for name in ('fit','sample'):
            with self.assertRaisesRegex(RuntimeError,'Read-only'):getattr(namespace['RevisedForestGenerator'],name)(None)
        with self.assertRaisesRegex(RuntimeError,'Read-only'):namespace['pickle'].load(None)
        with self.assertRaisesRegex(ValueError,'Forest source changed'):_forest_checker('0'*64)


class OriginalDeliveriesTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.reader=ReadOnlyArtifactReader(runtime.ROOT_DIR/'config/revision_generation_simple_20261020.json')
        cls.split=cls.reader._run.load('diabetes_prima_indian',13)

    def setUp(self):
        self.tmp=tempfile.TemporaryDirectory();self.addCleanup(self.tmp.cleanup)
        self.output=Path(self.tmp.name)
        self.identity,self.models,original=self.reader._run.paths(self.split,'ctgan')
        for path in original.iterdir():
            if path.is_file():shutil.copy2(path,self.output/path.name)

    def read_fixture(self):
        with patch.object(self.reader._run,'paths',return_value=(self.identity,self.models,self.output)):
            return self.reader.read(self.split.dataset,self.split.seed,'ctgan')

    def test_original_csv_load_and_strict_reader_remains_strict(self):
        frames=self.read_fixture()
        self.assertEqual([len(f) for f in frames],[700,700])
        strict=runtime.RevisedRun(runtime.PINNED_RUN,config_path=runtime.ROOT_DIR/'config/revision_generation_simple_20261020.json')
        with self.assertRaises(FileNotFoundError):runtime.load_samples(strict,self.split,'ctgan')

    def test_csv_byte_tampering_rejected(self):
        path=self.output/'synthetic_class_0.csv';path.write_bytes(path.read_bytes()+b'\n')
        with self.assertRaisesRegex(ValueError,'CSV hash mismatch'):self.read_fixture()

    def test_diagnostic_tampering_rejected(self):
        path=self.output/'validity_class_0.json';path.write_bytes(path.read_bytes()+b' ')
        with self.assertRaisesRegex(ValueError,'Diagnostic/raw'):self.read_fixture()

    def test_parameter_and_identity_tampering_rejected(self):
        path=self.output/'generator_parameters.json';path.write_text('{}')
        with self.assertRaisesRegex(ValueError,'parameter'):self.read_fixture()
        path=self.output/'identity.json';path.write_text('{}')
        with self.assertRaisesRegex(ValueError,'identity'):self.read_fixture()

    def test_labels_rejected_even_if_fixture_csv_hash_is_updated(self):
        path=self.output/'synthetic_class_0.csv';lines=path.read_text().splitlines()
        cells=lines[1].split(',');cells[-1]='1';lines[1]=','.join(cells)
        path.write_text('\n'.join(lines)+'\n')
        manifest_path=self.output/'samples_manifest.json';manifest=json.loads(manifest_path.read_text())
        manifest['files'][path.name]=hashlib.sha256(path.read_bytes()).hexdigest()
        manifest_path.write_text(json.dumps(manifest))
        with self.assertRaisesRegex(ValueError,'label'):self.read_fixture()

    def test_unrelated_code_hash_cannot_reuse_original_identity(self):
        real_digest=runtime.digest
        def changed(path):
            return '0'*64 if str(path).endswith('src/utils/seed_utils.py') else real_digest(path)
        with patch.object(runtime,'digest',side_effect=changed):
            with self.assertRaises(FileNotFoundError):self.reader.read(self.split.dataset,self.split.seed,'ctgan')

    def test_batch_read_reports_incompatible_code_instead_of_silently_skipping(self):
        real_digest=runtime.digest
        def changed(path):
            return '0'*64 if str(path).endswith('src/utils/seed_utils.py') else real_digest(path)
        with patch.object(runtime,'digest',side_effect=changed):
            with self.assertRaisesRegex(ValueError,'Existing delivery incompatible'):
                self.reader.read_completed()

    def test_forest_complete_delivery_keeps_model_guards_without_unpickling(self):
        with patch('pickle.load',side_effect=AssertionError('Model loading forbidden')):
            frames=self.reader.read('diabetes_prima_indian',13,'forestdiffusion')
        self.assertEqual([len(f) for f in frames],[700,700])


if __name__=='__main__':unittest.main()

