"""Supervised, explicitly real, small ForestDiffusion validation; benchmark stays blocked.

Only stdlib is imported here. Thread limits are set before the worker imports NumPy.
"""
import argparse
import hashlib
import json
import os
from pathlib import Path
import signal
import subprocess
import sys
import time

TIME_BUDGET_SECONDS = 600
RSS_BUDGET_BYTES = 2 * 1024**3
POLL_SECONDS = .1
THREAD_ENV = {name: "1" for name in ("OMP_NUM_THREADS", "OPENBLAS_NUM_THREADS", "MKL_NUM_THREADS",
             "NUMEXPR_NUM_THREADS", "VECLIB_MAXIMUM_THREADS", "BLIS_NUM_THREADS", "OMP_THREAD_LIMIT")}
THREAD_ENV["CUDA_VISIBLE_DEVICES"] = ""
PINNED_RUN = "33a9b4fce40753d94f4a3e2bf0c193f129e8edb5b6a19bb393544f747e2f3543"


def json_write(path, value):
    path.write_text(json.dumps(value, sort_keys=True, indent=2, allow_nan=False) + "\n")


def process_table(proc_root=Path("/proc")):
    table = {}
    for path in proc_root.glob("[0-9]*/status"):
        try:
            fields = dict(line.split(":", 1) for line in path.read_text().splitlines() if ":" in line)
            pid = int(path.parent.name)
            table[pid] = {"ppid": int(fields["PPid"]), "rss": int(fields.get("VmRSS", "0 kB").split()[0])*1024}
        except (OSError, ValueError, KeyError):
            continue  # A process can exit while procfs is sampled.
    return table


def family_resources(pid, table):
    family = {pid}
    while True:
        expanded = family | {p for p, info in table.items() if info["ppid"] in family}
        if expanded == family:
            break
        family = expanded
    # Include reparented workers that retained the validation process group.
    for p in table:
        try:
            if os.getpgid(p) == pid:
                family.add(p)
        except ProcessLookupError:
            pass
    members = {p: table[p]["rss"] for p in family if p in table}
    return {"rss_bytes": sum(members.values()), "members_rss_bytes": members}


def budget_reason(elapsed, rss):
    if elapsed > TIME_BUDGET_SECONDS:
        return "time"
    if rss > RSS_BUDGET_BYTES:
        return "aggregate_rss"
    return None


def immutable_inventory(root):
    files = [root / "data/original_source" / name for name in ("framingham.csv", "pima_indians_diabetes.csv",
             "Retinopathy_Diabetes.csv", "risk_factors_cervical_cancer.csv")]
    data = root / "data/processed_revision_a1" / PINNED_RUN
    files.extend(data / name for name in ("run_manifest.json", "summary.json", "summary.csv", "failures.json"))
    for ds in ("heart_framingham", "diabetes_prima_indian", "diabetic_retinopathy", "cervical_cancer"):
        for seed in (13, 23, 42, 69, 88):
            directory = data / ds / f"seed_{seed}"
            inventory = directory / "artifact_hashes.json"
            files.append(inventory)
            files.extend(directory / name for name in json.loads(inventory.read_text()))
    files.extend(root / name for name in ("config/params.json", "config/const.py", "src/revision_a1.py",
                 "main_prepare_revision_a1.py", "main_sampler.py", "src/generators/forestdiffusion.py"))
    return {str(p.relative_to(root)): hashlib.sha256(p.read_bytes()).hexdigest() for p in files}


def supervise(output, run_id):
    root = Path(__file__).resolve().parent
    output = output.resolve()
    output.mkdir(parents=True, exist_ok=False)
    started = time.perf_counter()
    before = immutable_inventory(root)
    json_write(output / "immutable_before.json", before)
    env = {**os.environ, **THREAD_ENV, "PYTHONDONTWRITEBYTECODE": "1"}
    command = [sys.executable, "-c", "from src.revision_forest_validation import run_worker; "
               "import sys; sys.exit(run_worker(sys.argv[1], sys.argv[2]))", str(output), run_id]
    json_write(output / "launch.json", {"execution_kind": "real_validation", "command": command,
               "thread_environment": THREAD_ENV, "time_budget_seconds": TIME_BUDGET_SECONDS,
               "rss_budget_bytes": RSS_BUDGET_BYTES, "poll_seconds": POLL_SECONDS,
               "full_benchmark": "blocked", "python_executable": sys.executable})
    peak, samples, reason = 0, 0, None
    with (output / "worker.stdout.log").open("xb") as stdout, (output / "worker.stderr.log").open("xb") as stderr, \
         (output / "resources.jsonl").open("x") as resources:
        process = subprocess.Popen(command, cwd=root, env=env, stdout=stdout, stderr=stderr, start_new_session=True)
        try:
            while True:
                table = process_table()
                sample = family_resources(process.pid, table)
                sample["elapsed_seconds"] = time.perf_counter()-started
                sample["supervisor_rss_bytes"] = table.get(os.getpid(), {}).get("rss", 0)
                sample["rss_with_supervisor_bytes"] = sample["rss_bytes"] + sample["supervisor_rss_bytes"]
                resources.write(json.dumps(sample) + "\n")
                resources.flush()
                samples += 1
                peak = max(peak, sample["rss_with_supervisor_bytes"])
                reason = budget_reason(sample["elapsed_seconds"], sample["rss_with_supervisor_bytes"])
                if reason or (process.poll() is not None and not sample["members_rss_bytes"]):
                    break
                time.sleep(POLL_SECONDS)
        finally:
            if process.poll() is None or reason:
                try:
                    os.killpg(process.pid, signal.SIGTERM)
                except ProcessLookupError:
                    pass
                try:
                    process.wait(timeout=.5)
                except subprocess.TimeoutExpired:
                    pass
                try:
                    os.killpg(process.pid, signal.SIGKILL)
                except ProcessLookupError:
                    pass
            process.wait()
    after = immutable_inventory(root)
    json_write(output / "immutable_after.json", after)
    status = "budget_exceeded" if reason else ("completed" if process.returncode == 0 else "failed")
    if before != after:
        status = "failed_immutable_hash_check"
    result = {"execution_kind": "real_validation", "status": status, "budget_exceeded_reason": reason,
              "worker_returncode": process.returncode, "elapsed_seconds": time.perf_counter()-started,
              "peak_sampled_rss_with_supervisor_bytes": peak, "resource_samples": samples,
              "immutable_inputs_unchanged": before == after, "immutable_files_checked": len(before),
              "time_budget_seconds": TIME_BUDGET_SECONDS, "rss_budget_bytes": RSS_BUDGET_BYTES,
              "rss_measurement": "sum live process-tree RSS; plus supervisor for budget; sampled every 0.1s",
              "full_benchmark": "blocked", "A1": "open", "A3": "open"}
    json_write(output / "supervision.json", result)
    # Include partial evidence even when the worker was stopped or failed.
    inventory = {str(p.relative_to(output)): hashlib.sha256(p.read_bytes()).hexdigest()
                 for p in sorted(output.rglob("*")) if p.is_file()}
    json_write(output / "artifact_hashes.json", inventory)
    print(json.dumps(result, indent=2))
    return 0 if status == "completed" else 1


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--revision-a1-run", required=True, choices=[PINNED_RUN])
    parser.add_argument("--output", required=True, type=Path)
    args = parser.parse_args()
    raise SystemExit(supervise(args.output, args.revision_a1_run))

