"""Prepare, then execute ONCE the resource-supervised real minimal GReaT trial."""
import argparse
import os
from pathlib import Path
import signal
import subprocess
import sys
import time
import traceback

from src.revision_great_validation import ROOT, ENV, check_contract, prepare, read, require, sha, write


def process_table(proc=Path('/proc')):
    table = {}
    for file in proc.glob('[0-9]*/status'):
        try:
            fields = dict(line.split(':', 1) for line in file.read_text().splitlines() if ':' in line)
            table[int(file.parent.name)] = {'ppid': int(fields['PPid']),
                'rss': int(fields.get('VmRSS', '0 kB').split()[0])*1024}
        except (OSError, ValueError, KeyError):
            pass
    return table


def family_resources(pid, table):
    family = {pid}
    while True:
        expanded = family | {p for p, item in table.items() if item['ppid'] in family}
        if expanded == family:
            break
        family = expanded
    for p in table:
        try:
            if os.getpgid(p) == pid:
                family.add(p)
        except ProcessLookupError:
            pass
    members = {p: table[p]['rss'] for p in family if p in table}
    return {'members_rss_bytes': members, 'worker_tree_rss_bytes': sum(members.values())}


def budget_reason(elapsed, rss, budget):
    if elapsed > budget['seconds']:
        return 'time'
    if rss > budget['rss_bytes']:
        return 'aggregate_rss'
    return None


def terminate_family(process, members):
    for sig in (signal.SIGTERM, signal.SIGKILL):
        try:
            os.killpg(process.pid, sig)
        except ProcessLookupError:
            pass
        for pid in members:
            if pid != os.getpid():
                try:
                    os.kill(pid, sig)
                except ProcessLookupError:
                    pass
        if sig == signal.SIGTERM:
            time.sleep(.5)
    process.wait()


def supervise(output):
    output = Path(output).resolve()
    # The supervisor stays stdlib-only: validate the immutable plan without
    # importing the neural stack. Full runtime checks also run inside the worker.
    plan = read(output/'plan.json')
    require(sha(output/'plan.json') == (output/'plan.sha256').read_text().strip(), 'Plan changed')
    require(sha(output/'protected_before.json') == plan['protected_inventory_sha256'], 'Protected inventory changed')
    before = read(output/'protected_before.json')
    require(all(sha(ROOT/p) == h for p, h in before.items()), 'Protected input changed before launch')
    require(all(sha(ROOT/p) == h for p, h in plan['validation_code_sha256'].items()), 'Runner changed after plan')
    with (output/'execution_started.json').open('x') as stream:
        stream.write('{"one_shot_launch": true}\n')  # Never rerun a failed/completed plan.
    command = [sys.executable, str(Path(__file__).resolve()), '--worker', str(output)]
    write(output/'launch.json', {'command': command, 'plan_sha256': sha(output/'plan.json'), 'environment': ENV})
    budget, phase_peaks = plan['budget'], {}
    peak, reason, process, latest_members = 0, None, None, {}
    started = time.monotonic()
    with (output/'worker.stdout.log').open('x') as stdout, (output/'worker.stderr.log').open('x') as stderr, \
         (output/'resources.jsonl').open('x') as resources:
        process = subprocess.Popen(command, cwd=ROOT, env={**os.environ, **ENV},
            stdout=stdout, stderr=stderr, start_new_session=True)
        try:
            while True:
                table = process_table()
                sample = family_resources(process.pid, table)
                latest_members = sample['members_rss_bytes']
                elapsed = time.monotonic()-started
                phase = read(output/'phase.json')['phase'] if (output/'phase.json').exists() else 'worker_startup'
                sample.update(elapsed_seconds=elapsed, monotonic=time.monotonic(), phase=phase,
                    supervisor_rss_bytes=table.get(os.getpid(), {}).get('rss', 0))
                sample['aggregate_rss_bytes'] = sample['worker_tree_rss_bytes']+sample['supervisor_rss_bytes']
                resources.write(__import__('json').dumps(sample)+'\n')
                resources.flush()
                peak = max(peak, sample['aggregate_rss_bytes'])
                phase_peaks[phase] = max(phase_peaks.get(phase, 0), sample['aggregate_rss_bytes'])
                reason = budget_reason(elapsed, sample['aggregate_rss_bytes'], budget)
                if reason or (process.poll() is not None and not latest_members):
                    break
                time.sleep(budget['poll_seconds'])
        finally:
            if process.poll() is None or reason:
                terminate_family(process, latest_members)
            else:
                process.wait()
    changed = [p for p, h in before.items() if not (ROOT/p).is_file() or sha(ROOT/p) != h]
    summary = {'status': 'budget_exceeded' if reason else ('completed' if process.returncode == 0 else 'failed'),
        'worker_returncode': process.returncode, 'budget_exceeded_reason': reason,
        'seconds': time.monotonic()-started, 'peak_sampled_aggregate_rss_bytes': peak,
        'phase_peak_sampled_aggregate_rss_bytes': phase_peaks, 'budget': budget,
        'immutable_files_checked': len(before), 'changed_protected_files': changed,
        'plan_unchanged': sha(output/'plan.json') == (output/'plan.sha256').read_text().strip(),
        'gpu_memory_bytes': None, 'device': 'cpu', 'benchmark': 'blocked', 'A1_A5': 'open'}
    if changed or not summary['plan_unchanged']:
        summary['status'] = 'integrity_failure'
    write(output/'supervision.json', summary)
    write(output/'artifact_hashes.json', {str(p.relative_to(output)): sha(p) for p in sorted(output.rglob('*'))
                                        if p.is_file() and p.name != 'artifact_hashes.json'})
    print(__import__('json').dumps(summary, indent=2))
    return 0 if summary['status'] == 'completed' else 1


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument('--prepare', type=Path, metavar='NEW_OUTPUT')
    group.add_argument('--execute-plan', type=Path, metavar='OUTPUT')
    group.add_argument('--worker', type=Path, help=argparse.SUPPRESS)
    args = parser.parse_args()
    os.environ.update(ENV)
    if args.prepare:
        plan = prepare(args.prepare)
        print('Immutable plan:', args.prepare/'plan.json', plan['runtime_identity_sha256'])
        return 0
    if args.execute_plan:
        return supervise(args.execute_plan)
    from src.revision_great_validation import worker
    require((args.worker/'execution_started.json').is_file(), 'Worker requires one-shot supervised launch')
    try:
        return worker(args.worker)
    except Exception as exc:
        write(args.worker/'worker_failure.json', {'type': type(exc).__name__, 'message': str(exc),
              'traceback': traceback.format_exc(), 'phase': read(args.worker/'phase.json')
              if (args.worker/'phase.json').exists() else 'startup'})
        traceback.print_exc()
        return 1


if __name__ == '__main__':
    raise SystemExit(main())

