#!/usr/bin/env python
"""Read existing /proc, JSON, CSV and logs only. Never imports or loads models."""
import argparse
from collections import Counter, defaultdict, deque
import csv
from datetime import datetime, timezone
import hashlib
import json
import math
import os
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parent
RUN = '33a9b4fce40753d94f4a3e2bf0c193f129e8edb5b6a19bb393544f747e2f3543'


def read(path):
    return json.loads(path.read_text())


def sha(path):
    h = hashlib.sha256()
    with path.open('rb') as stream:
        for block in iter(lambda: stream.read(1024*1024), b''):
            h.update(block)
    return h.hexdigest()


def tail(path, size=8000):
    with path.open('rb') as stream:
        stream.seek(max(0, path.stat().st_size-size))
        return stream.read().decode(errors='replace')


def processes(root_pid, full_pids=False):
    table = {}
    for path in Path('/proc').glob('[0-9]*/stat'):
        try:
            text = path.read_text(); fields = text[text.rfind(')')+2:].split()
            table[int(path.parent.name)] = {
                'ppid':int(fields[1]), 'state':fields[0], 'rss':int(fields[21])*os.sysconf('SC_PAGE_SIZE'),
                'threads':int(fields[17]), 'ticks':int(fields[11])+int(fields[12]), 'start':int(fields[19])}
        except (OSError, ValueError, IndexError):
            continue
    if root_pid not in table:
        print(f'PID {root_pid} no visible: puede haber terminado o estar fuera de este espacio de procesos.')
        return []
    family = {root_pid}
    while True:
        expanded = family | {pid for pid, item in table.items() if item['ppid'] in family}
        if family == expanded:break
        family = expanded
    uptime = float(Path('/proc/uptime').read_text().split()[0]); hz = os.sysconf('SC_CLK_TCK')
    active = []; kinds = Counter(); pids = []
    for pid in sorted(family):
        item = table[pid]
        try:words = [w for w in Path(f'/proc/{pid}/cmdline').read_bytes().decode(errors='replace').split('\0') if w]
        except OSError:continue
        if pid == root_pid or 'main_sampler.py' in words:
            elapsed = max(0, uptime-item['start']/hz)
            cpu = 100*item['ticks']/hz/elapsed if elapsed else 0
            print(f"PID {pid} PPID {item['ppid']} estado={item['state']} CPU_media={cpu:.1f}% RSS={item['rss']/1024**2:.1f}MiB hilos={item['threads']} transcurrido={elapsed:.0f}s")
            if 'main_sampler.py' in words:
                model = words[words.index('--models')+1] if '--models' in words else '?'
                active.append(model)
                print('  '+ ' '.join(words))
                try:print('  cwd:',os.readlink(f'/proc/{pid}/cwd'))
                except OSError:pass
        else:
            command = ' '.join(words)
            kinds['loky' if 'popen_loky' in command else 'resource_tracker' if 'resource_tracker' in command else 'otros'] += 1
            pids.append(pid)
    rss = sum(table[pid]['rss'] for pid in family)
    print(f'Descendientes: {len(family)-1}; auxiliares={dict(kinds)}; RSS agregado={rss/1024**3:.2f}GiB (suma, incluye memoria compartida).')
    if pids:
        print('PID auxiliares:', ','.join(map(str,pids if full_pids else pids[:8])),
              '' if full_pids or len(pids)<=8 else f'... (+{len(pids)-8}; --full-pids para todos)')
    return active


def completed(directory, identity, quota):
    manifest = read(directory/'samples_manifest.json')
    if manifest['identity'] != identity:raise ValueError('identidad del manifiesto distinta')
    names = {f'synthetic_class_{label}.csv' for label in (0,1)}
    if set(manifest['files']) != names:raise ValueError('inventario CSV incompleto')
    meta = ROOT/'data/processed_revision_a1'/RUN/identity['dataset']/f"seed_{identity['seed']}"/'feature_meta.json'
    if sha(meta) != identity['artifact_hashes']['feature_meta.json']:raise ValueError('metadatos de columnas incompatibles')
    columns = read(meta)['feature_names']+['class']
    counts = []
    for label in (0,1):
        path = directory/f'synthetic_class_{label}.csv'
        if sha(path) != manifest['files'][path.name]:raise ValueError('hash CSV distinto')
        with path.open(newline='') as stream:
            reader = csv.reader(stream)
            if next(reader) != columns:raise ValueError('orden/esquema CSV distinto')
            count = 0
            for row in reader:
                if len(row) != len(columns) or not all(math.isfinite(float(v)) for v in row) or float(row[-1]) != label:
                    raise ValueError('fila incompleta, no finita o etiqueta inválida')
                count += 1
        if count != quota:raise ValueError(f'cuota clase {label}: {count}/{quota}')
        counts.append(count)
    for name, digest in manifest.get('observability_files',{}).items():
        if Path(name).name != name or sha(directory/name) != digest:raise ValueError('diagnóstico/raw sin hash compatible')
    return counts


def progress_files(models, workspace):
    """Report persisted progress only, never infer epoch from a checkpoint number."""
    found = []
    for base in (models, workspace):
        if not base.is_dir():continue
        for directory, children, files in os.walk(base):
            children[:] = [name for name in children if not name.startswith(('revision_great','revision_tabpfgen','.')) and name not in ('cache','data')]
            for name in files:
                path = Path(directory)/name
                if name not in ('trainer_state.json','progress-messages.csv') and not name.endswith('.log'):continue
                try:found.append((path.stat().st_mtime,path))
                except OSError:pass
    for _, path in sorted(found, reverse=True)[:4]:
        print('    progreso/log:',path.relative_to(ROOT))
        try:
            if path.name == 'trainer_state.json':
                state=read(path)
                print('      registrado:',{k:state.get(k) for k in ('epoch','global_step','max_steps')})
                if state.get('log_history'):print('      último log:',state['log_history'][-1])
            elif path.name == 'progress-messages.csv':
                with path.open() as stream:last=deque(csv.DictReader(stream),maxlen=1)
                print('      último registro:',dict(last[0]) if last else 'vacío')
            else:print('      '+tail(path,1200).splitlines()[-1])
        except (OSError,ValueError,IndexError):print('      lectura parcial; vuelva a consultar')
    if not found:print('    Sin log interno ni trainer_state/progress-messages persistidos en esta combinación.')


def partial_detail(directory):
    relative=directory.relative_to(ROOT/'results'); models=ROOT/'models'/relative; workspace=ROOT/'train_model_info'/relative
    print('    artefactos:',directory.relative_to(ROOT))
    for label in (0,1):
        path=directory/f'synthetic_class_{label}.csv'
        if path.is_file():
            try:
                with path.open(newline='') as stream:rows=max(0,sum(1 for _ in csv.reader(stream))-1)
                print(f'    clase {label}: CSV con {rows} filas; combinación todavía sin cierre válido.')
            except OSError:pass
        class_dir=models/f'class_{label}'
        if (class_dir/'revision_sdv_binding.json').is_file():
            print(f'    clase {label}: binding SDV de modelo guardado presente (no se carga el modelo).')
        elif (class_dir/'revision_sdv_metadata.json').is_file():
            print(f'    clase {label}: fit iniciado/metadatos preparados; ajuste y guardado final aún no acreditados.')
        elif class_dir.exists():print(f'    clase {label}: directorio creado; fase interna no registrada.')
        diagnostic=directory/f'validity_class_{label}.json'
        if diagnostic.is_file():
            try:
                d=read(diagnostic)
                print(f"    diagnóstico clase {label}: {d.get('status')}; entregadas={d.get('delivered_rows')}")
            except (OSError,ValueError):pass
    forest=directory/'forest_execution.json'
    if forest.is_file():
        try:
            record=read(forest)
            print('    Forest registrado:',record.get('status'),[(c.get('label'),c.get('status')) for c in record.get('classes',[])])
        except (OSError,ValueError):pass
    for audit in models.glob('class_*/revision_sampling_parameters.json'):
        try:
            a=read(audit)
            print('    TabuLa',audit.parent.name,{k:a.get(k) for k in ('status','internal_generate_calls_observed','internal_candidates_observed','accepted_rows_observed','termination')})
        except (OSError,ValueError):pass
    progress_files(models,workspace)


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--pid',type=int,default=407411)
    parser.add_argument('--full-pids',action='store_true',help='Print every auxiliary PID instead of a compact preview')
    args=parser.parse_args()
    config=read(ROOT/'config/revision_generation_simple_20261020.json'); experiment=config['experiment']
    print(datetime.now(timezone.utc).isoformat(),'UTC; monitor de solo lectura')
    active=processes(args.pid,args.full_pids)
    log=ROOT/'logs/generacion_definitiva/salida.log'
    if log.is_file():
        print('\nÚltimo log general (las barras con retorno de carro se separan):')
        lines=[line for line in re.split('[\r\n]',tail(log)) if line.strip()]
        print('\n'.join(line[-300:] for line in lines[-5:]))
    entries=defaultdict(list)
    for path in (ROOT/'results/revision_a1'/RUN).glob('*/*/*/*/identity.json'):
        try:
            identity=read(path)
            if identity.get('config') != config or identity.get('run_id') != RUN:continue
            entries[(identity['model'],identity['dataset'],identity['seed'])].append((path.parent,identity))
        except (OSError,ValueError,KeyError):continue
    partials=[];summary=[]
    for model in experiment['models']:
        counts=Counter(); finished=defaultdict(list)
        for dataset in experiment['datasets']:
            for seed in experiment['seeds']:
                matches=entries.get((model,dataset,seed),[])
                if not matches:counts['sin_iniciar']+=1;continue
                if len(matches)!=1:counts['ambiguas']+=1;continue
                directory,identity=matches[0]
                try:completed(directory,identity,experiment['n_samples_per_class'])
                except (OSError,ValueError,KeyError,StopIteration,csv.Error) as exc:
                    counts['parciales']+=1
                    partials.append((model,dataset,seed,directory,str(exc)))
                else:counts['completas']+=1;finished[dataset].append(seed)
        summary.append(f"{model:17} completas={counts['completas']:2}/20 parciales={counts['parciales']:2} sin_iniciar={counts['sin_iniciar']:2} ambiguas={counts['ambiguas']}")
        for dataset,seeds in finished.items():summary.append(f'  COMPLETAS {dataset}: seeds {seeds}; {experiment["n_samples_per_class"]}/{experiment["n_samples_per_class"]} filas por combinación.')
    for model,dataset,seed,directory,reason in partials:
        print(f'\nPARCIAL {model} {dataset} seed={seed} '+ ('(generador activo)' if model in active else '(actividad no acreditada por esta vista de procesos)'))
        print('    cierre no acreditado:',reason)
        partial_detail(directory)
    print('\nCombinaciones: COMPLETA exige manifiesto, identidad, hashes, esquema, finitud, etiquetas y cuota; no evalúa calidad ni carga modelos.')
    print('\n'.join(summary))
    print('\nAusencia de un manifiesto válido indica parcial, no demuestra fallo. No se estima porcentaje de entrenamiento ni tiempo restante.')


if __name__=='__main__':main()

